from flask import Flask, request, jsonify
import flask_tasks
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash

db = SQLAlchemy()

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), unique=True)
    password_hash = db.Column(db.String(128))

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

def create_app():
    app = Flask(__name__)
    app.config.update(
        SECRET_KEY='secret_key',
        SQLALCHEMY_DATABASE_URI='sqlite:////path/to/your/database.db',
        SQLALCHEMY_TRACK_MODIFICATIONS=False
    )
    db.init_app(app)

    def _bad_request(message, status=400):
        return jsonify(error=message), status

    @app.route('/health')
    def health():
        return jsonify(status='ok')

    @app.route('/login', methods=['POST'])
    def login():
        data = request.get_json()
        if not data or not data.get('username') or not data.get('password'):
            return _bad_request("must include username and password")
        user = User.query.filter_by(username=data.get('username')).first()
        if not user or not user.check_password(data.get('password')):
            return _bad_request("invalid username or password")
        return jsonify(message="logged in successfully")

    @app.route('/register', methods=['POST'])
    def register():
        data = request.get_json()
        if not data or not data.get('username') or not data.get('password'):
            return _bad_request("must include username and password")
        user = User.query.filter_by(username=data.get('username')).first()
        if user:
            return _bad_request("username already taken")
        new_user = User(username=data.get('username'))
        new_user.set_password(data.get('password'))
        db.session.add(new_user)
        db.session.commit()
        return jsonify(message="user created successfully"), 201

    return app

if __name__ == "__main__":
    app = create_app()
    app.run(debug=False)

from flask import Flask, render_template, request, redirect, url_for, send_from_directory
import flask_tasks
from werkzeug import secure_filename
import os

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploads/'
app.config['ALLOWED_EXTENSIONS'] = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1] in app.config['ALLOWED_EXTENSIONS']

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload():
    file = request.files['file']
    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
        return redirect(url_for('uploaded_file', filename=filename))

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

if __name__ == "__main__":
    app.run('0.0.0.0', port=8000)

