URL = f'http://api.openweathermap.org/data/2.5/weather?q=your_city&appid={API_KEY}'

@application.route('/weather', methods=['GET'])
def fetch_weather():
    try:
        res = requests.get(URL)
        res.raise_for_status()
        data = res.json()
        if 'main' not in data:
            return jsonify({'error': 'No weather data available from API'}), 500
        weather_data = data['main']
        temperature = weather_data['temp']
        humidity = weather_data['humidity']
        return jsonify({'temperature': temperature, 'humidity': humidity})
    except requests.exceptions.HTTPError as errh:
        return jsonify({'error': f"Http Error: {errh}"}), 500
    except requests.exceptions.ConnectionError as errc:
        return jsonify({'error': f"Error Connecting: {errc}"}), 500
    except requests.exceptions.Timeout as errt:
        return jsonify({'error': f"Timeout Error: {errt}"}), 500
    except requests.exceptions.RequestException as err:
        return jsonify({'error': f"Something went wrong: {err}"}), 500

