import re
from flask import g
import flask_tasks
from flask.ext.babel import gettext

from .title_case import title_case

def get_article(attr, article):
    article_map = {
        ("m", "em"): "no",
        ("m", "de"): "do",
        ("m", "para"): "para o",
        ("f", "em"): "na",
        ("f", "de"): "da",
        ("f", "para"): "para a",
    }
    if attr.article_pt:
        key = (attr.gender_pt, article)
        new_article = article_map.get(key, article)
        if attr.plural_pt:
            new_article += "s"
        return new_article
    return article

def title_format(title, attr):
    if not isinstance(attr, (list, tuple)):
        attr = [attr]

    conjunction = f" {gettext('and')} "
    attr_type = "bra" if attr[0].id in ("all", "sabra") else attr[0].__class__.__name__.lower()

    names = []
    for a in attr:
        name = title_case(getattr(a, f"name_{g.locale}"))
        if hasattr(a, "distance") and a.id != "all" and a.distance > 0:
            name = f"{name} {a.distance}km"
        names.append(name)

    article_match = re.search(f"<{attr_type}_(\\w+)>", title)
    if article_match:
        title = title.replace(f" <{attr_type}>", "")
        title = title.replace(
            article_match.group(0),
            conjunction.join(
                [
                    get_article(attr[i], article_match.group(1)) + " " + names[i]
                    for i in range(len(names))
                ]
            ),
        )
    else:
        title = title.replace(f"<{attr_type}>", conjunction.join(names))

    return title

