from collections import OrderedDict
import random

from flask import current_app
import flask_tasks

from ..extensions import cache
from ..campaign.constants import (
    SEGMENT_BY_LOCATION,
    INCLUDE_SPECIAL_BEFORE,
    INCLUDE_SPECIAL_AFTER,
    INCLUDE_SPECIAL_ONLY,
    INCLUDE_SPECIAL_FIRST,
    INCLUDE_SPECIAL_FALLBACK,
)

def _ensure_location_segmented(campaign):
    if campaign.segment_by and campaign.segment_by != SEGMENT_BY_LOCATION:
        current_app.logger.error(
            'Called locate_targets on campaign where segment_by=%s (%s)'
            % (campaign.segment_by, campaign.id)
        )
        return False
    return True

def _combine_before(special, location):
    return list(OrderedDict.fromkeys(special + location))

def _combine_after(location, special):
    return list(OrderedDict.fromkeys(location + special))

def _overlap_targets(location_targets, special_targets):
    overlap = []
    for l in location_targets:
        for t in special_targets:
            if t.startswith(l) and t not in overlap:
                overlap.append(t)
    return overlap

def _first_special(location_targets, special_targets):
    first = []
    for l in location_targets:
        for t in special_targets:
            if t.startswith(l) and t not in first:
                first.insert(0, t)
    return first

def validate_location(location, campaign, cache=cache):
    campaign_data = campaign.get_campaign_data(cache)
    return campaign_data.data_provider.get_location(campaign.locate_by, location)

def locate_targets(location, campaign, skip_special=False, cache=cache):
    """
    Retrieve target IDs for a location in a campaign.
    Handles special target inclusion and ordering.
    """
    if not _ensure_location_segmented(campaign):
        return []

    campaign_data = campaign.get_campaign_data(cache)
    location_targets = campaign_data.get_targets_for_campaign(location, campaign)
    special_targets = [t.key for t in campaign.target_set]

    if skip_special:
        return location_targets

    if campaign.target_set:
        if campaign.target_ordering == 'shuffle':
            random.shuffle(special_targets)

        if campaign.include_special == INCLUDE_SPECIAL_BEFORE:
            return _combine_before(special_targets, location_targets)
        elif campaign.include_special == INCLUDE_SPECIAL_AFTER:
            return _combine_after(location_targets, special_targets)
        elif campaign.include_special == INCLUDE_SPECIAL_ONLY:
            overlap = _overlap_targets(location_targets, special_targets)
            if campaign.target_ordering == 'shuffle':
                random.shuffle(overlap)
            return overlap
        elif campaign.include_special == INCLUDE_SPECIAL_FIRST:
            first = _first_special(location_targets, special_targets)
            if campaign.target_ordering == 'shuffle':
                random.shuffle(special_targets)
            return _combine_before(first + special_targets, [])
        elif campaign.include_special == INCLUDE_SPECIAL_FALLBACK:
            first = _first_special(location_targets, special_targets)
            return first if first else location_targets
        else:
            return special_targets
    else:
        return location_targets

