from flask_pymongo import PyMongo
from flask_cryptography import FlaskCryptography
import schedule
import time
import threading

app = Flask(__name__)
app.config["MONGO_URI"] = "mongodb://localhost:27017/myDatabase"
app.config['CRYPTOGRAPHY_SECRET_KEY'] = 'your-secret-key'

mongo = PyMongo(app)
crypto = FlaskCryptography(app)

@app.route('/health')
def health():
    return {'status': 'ok'}

@app.route('/get_data', methods=['GET'])
def get_data():
    encrypted = mongo.db.collection.find_one({"some_field": "some_value"})
    data = crypto.decrypt(encrypted)
    return data

@app.route('/insert_data', methods=['POST'])
def insert_data():
    data = request.json
    encrypted = crypto.encrypt(data)
    mongo.db.collection.insert_one(encrypted)
    return {'message': 'data inserted successfully'}

def periodic_reencryption():
    for doc in mongo.db.collection.find():
        decrypted = crypto.decrypt(doc)
        encrypted = crypto.encrypt(decrypted)
        mongo.db.collection.update_one({'_id': doc['_id']}, {'$set': encrypted})

schedule.every(1).days.do(periodic_reencryption)

def scheduler_worker():
    while True:
        schedule.run_pending()
        time.sleep(1)

if __name__ == '__main__':
    threading.Thread(target=scheduler_worker, daemon=True).start()
    app.run(host='0.0.0.0')

