import json
import os
from flask import Flask, make_response, request
import flask_tasks
from flask_cors import CORS
from cltk.corpus.greek.beta_to_unicode import Replacer

import db

parse_beta = Replacer().beta_code

def _flatten_line(line):
    return line['#text'] if isinstance(line, dict) else line

def _load_odyssey(book=None, lines=None, lang="gk"):
    path = os.environ['HOMER_PATH']
    with open(f"{path}/hom.od_{lang}.xml.json") as fp:
        odyssey_dict = json.load(fp)

    res = odyssey_dict['TEI.2']['text']['body']['div1']

    if lang == "gk":
        if book and lines:
            return _flatten_line([res[book - 1]['l'][line]])
        elif book:
            return [parse_beta(_flatten_line(x).upper()) for x in res[book - 1]['l']]
        return res
    return res[book - 1]['p']['#text']

def _post_interactions():
    data = request.get_json()
    interaction = db.create_interaction(
        typee=data["type"],
        fromm=data["from"],
        to=data["to"],
        sel=data["selection"],
        book=int(data["book"])
    )
    return make_response(json.dumps(interaction._store), 200)

def _get_interactions():
    book = request.args.get("book")
    book = int(book) if book is not None else None
    interactions = db.fetch_interactions(book=book)
    cleaned = []
    for x in interactions:
        x.pop('_key', None)
        x.pop('_rev', None)
        x['selection'].pop('from_offset', None)
        x['selection'].pop('to_offset', None)
        x['_id'] = x['_id'].replace('Interactions/', '')
        x['_from'] = x['_from'].replace('Entities/', '')
        x['_to'] = x['_to'].replace('Entities/', '')
        cleaned.append(x)
    return make_response(json.dumps(cleaned), 200)

def _post_entities():
    data = request.get_json()
    entity = db.create_entity(
        name=data["name"],
        metadata=data["metadata"],
        typee=data["type"]
    )
    return make_response(json.dumps(entity._store), 200)

def _get_entities():
    entities = db.db["Entities"].fetchAll(rawResults=True)
    cleaned = []
    for x in entities:
        x['_id'] = x['_id'].replace('Entities/', '')
        cleaned.append(x)
    return make_response(json.dumps(cleaned), 200)

def create_app():
    app = Flask(__name__)
    CORS(app)

    @app.route('/')
    def root():
        return 'Welcome, to Flask!'

    @app.route('/book/<int:book>')
    def book(book):
        data = {
            'no': book,
            'greek': {'lines': _load_odyssey(book=book, lang="gk")},
            'english': {'text': _load_odyssey(book=book, lang="eng")}
        }
        return make_response(json.dumps(data), 200)

    @app.route('/book/<int:book>/lines/<lines>')
    def book_lines(book, lines):
        line_from, line_to = lines.split('-')
        data = {
            'book': {
                'book_no': book,
                'line_no': lines,
                'lines': _load_odyssey(book, [line_from, line_to])
            }
        }
        return make_response(json.dumps(data), 200)

    @app.route('/linenos')
    def linenos():
        odyssey = _load_odyssey()
        line_nos = [len(x['l']) for x in odyssey]
        return make_response(json.dumps(line_nos), 200)

    @app.route('/interactions', methods=['GET', 'POST'])
    def interactions():
        return _post_interactions() if request.method == 'POST' else _get_interactions()

    @app.route('/entities', methods=['GET', 'POST'])
    def entities():
        return _post_entities() if request.method == 'POST' else _get_entities()

    @app.route('/entities/bridges')
    def bridges():
        bridges = db.fetch_bridges()
        cleaned = []
        for x in bridges:
            x['from'] = x['from'].replace('Entities/', '')
            x['to'] = x['to'].replace('Entities/', '')
            cleaned.append(x)
        return make_response(json.dumps(cleaned), 200)

    @app.route('/entities/closenesses')
    def closeness():
        closenesses = db.get_closenesses()
        return make_response(json.dumps(closenesses), 200)

    @app.route('/percentdone')
    def percent_done():
        interactions = list(db.fetch_interactions())
        max_book = max(x['book'] for x in interactions)
        max_line = max(x['selection']['to_line'] for x in interactions if x['book'] == max_book)
        odyssey = _load_odyssey()
        line_nos = [len(x['l']) for x in odyssey]
        total_lines = sum(line_nos)
        total_done_lines = sum(line_nos[:max_book - 1]) + max_line
        data = {
            'percent': (total_done_lines / total_lines) * 100,
            'stats': {
                'current_book': max_book,
                'books_left': 24 - max_book,
                'lines_left': total_lines - total_done_lines,
                'lines_left_in_current_book': line_nos[max_book - 1] - max_line,
                'total_interactions': len(interactions)
            }
        }
        return make_response(json.dumps(data), 200)

    @app.route('/striplines')
    def strip_lines():
        return make_response(json.dumps(db.strip_lines()), 200)

    return app

if __name__ == "__main__":
    application = create_app()
    application.run(debug=True)

