weather_url = 'http://api.openweathermap.org/data/2.5/weather?q={}&units=metric&appid=your_openweather_api_key'

def create_app():
    app = Flask(__name__)
    app.config['DEBUG'] = False

    @app.route('/', methods=['GET', 'POST'])
    def weather():
        if request.method == 'POST':
            city = request.form['city']
            weather_data = requests.get(weather_url.format(city)).json()

            weather = {
                'city': city,
                'temperature': weather_data['main']['temp'],
                'description': weather_data['weather'][0]['description'],
            }
            return render_template('weather.html', weather=weather)
        else:
            return render_template('index.html')

    return app

if __name__ == "__main__":
    application = create_app()
    application.run(host='0.0.0.0', port=5000, debug=application.config['DEBUG'])

