import time
import functools

from rest_framework import status as http_status
from flask import request
import flask_tasks

from framework.auth import cas
from framework.auth import signing
from framework.flask import redirect
from framework.exceptions import HTTPError
from .core import Auth
from website import settings


# --------------------------------------------------------------------------- #
# Decorator: must_be_signed_decorator
# --------------------------------------------------------------------------- #
def must_be_signed_decorator(func):
    """Verify HMAC signature on the request payload."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        if request.method in ('GET', 'DELETE'):
            data = request.args
        else:
            data = request.get_json()

        try:
            signature = data['signature']
            payload = signing.unserialize_payload(data['payload'])
            exp_time = payload['time']
        except (KeyError, ValueError):
            raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                'message_short': 'Invalid payload',
                'message_long': 'The request payload could not be deserialized.'
            })

        if not signing.default_signer.verify_payload(signature, payload):
            raise HTTPError(http_status.HTTP_401_UNAUTHORIZED)

        if time.time() > exp_time:
            raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                'message_short': 'Expired',
                'message_long': 'Signature has expired.'
            })

        kwargs['payload'] = payload
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: block_bing_preview_decorator
# --------------------------------------------------------------------------- #
def block_bing_preview_decorator(func):
    """
    Temporary fix to prevent BingPreview from pre-fetching confirmation links.
    """
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        ua = request.headers.get('User-Agent')
        if ua and ('BingPreview' in ua or 'MSIE 9.0' in ua):
            return HTTPError(
                http_status.HTTP_403_FORBIDDEN,
                data={'message_long':
                      f'Internet Explorer 9 and BingPreview cannot be used to access this page '
                      f'for security reasons. Please use another browser. If this should not have '
                      f'occurred and the issue persists, please report it to <a href="mailto: '
                      f'{settings.OSF_SUPPORT_EMAIL}">{settings.OSF_SUPPORT_EMAIL}</a>.'}
            )
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: collect_auth_decorator
# --------------------------------------------------------------------------- #
def collect_auth_decorator(func):
    """Add an Auth object to kwargs based on request.args."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: must_be_confirmed_decorator
# --------------------------------------------------------------------------- #
def must_be_confirmed_decorator(func):
    """Require a user to be confirmed; raise appropriate HTTP errors."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        from osf.models import OSFUser

        user = OSFUser.load(kwargs['uid'])
        if user is not None:
            if user.is_confirmed:
                return func(*args, **kwargs)
            raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                'message_short': 'Account not yet confirmed',
                'message_long': 'The profile page could not be displayed as the user has not confirmed the account.'
            })
        raise HTTPError(http_status.HTTP_404_NOT_FOUND)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: must_be_logged_in_decorator
# --------------------------------------------------------------------------- #
def must_be_logged_in_decorator(func):
    """
    Require that a user be logged in; redirect to CAS login if not.
    """
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
        if kwargs['auth'].logged_in:
            return func(*args, **kwargs)
        return redirect(cas.get_login_url(request.url))

    return wrapped

