from flask import flash
import flask_tasks
from flask.ext.admin.contrib.sqla import ModelView
from studio.core.engines import db
from microsite.models import ChannelModel, ArticleModel

class ChannelView(ModelView):
    """
    Admin view for ChannelModel that prevents deletion when linked ArticleModels exist
    and removes 'articles' and 'all_articles' fields from create/edit forms.
    """
    column_labels = {'name': '名称', 'introduction': '简介'}

    def __init__(self, session=db.session, **kwargs):
        super(ChannelView, self).__init__(ChannelModel, session, **kwargs)

    def _has_linked_articles(self, channel):
        return ArticleModel.query.filter_by(cid=channel.id).first() is not None

    def delete_model(self, model):
        if self._has_linked_articles(model):
            flash('有文章关联，不能删除!')
            return False
        return super(ChannelView, self).delete_model(model)

    def _strip_unwanted_fields(self, form):
        if hasattr(form, 'articles'):
            delattr(form, 'articles')
        if hasattr(form, 'all_articles'):
            delattr(form, 'all_articles')
        return form

    def create_form(self, obj=None):
        form = super(ChannelView, self).create_form()
        return self._strip_unwanted_fields(form)

    def edit_form(self, obj=None):
        form = super(ChannelView, self).edit_form()
        return self._strip_unwanted_fields(form)

