def _handle_login_post():
    if request.form['username'] != app.config['USERNAME']:
        return 'Invalid username'
    if request.form['password'] != app.config['PASSWORD']:
        return 'Invalid password'
    session['logged_in'] = True
    flash('You were logged in')
    return redirect(url_for('show_entries'))

def _perform_logout():
    session.pop('logged_in', None)
    flash('You were logged out')
    return redirect(url_for('show_entries'))

# VIEW FUNCTIONS
@app.route('/login', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        result = _handle_login_post()
        if isinstance(result, str):
            error = result
        else:
            return result
    return render_template('login.html', error=error)

@app.route('/logout')
def logout():
    return _perform_logout()

@app.route('/')
def show_entries():
    db = get_db()
    return render_template('layout.html')

@app.route('/add', methods=['POST'])
def add_entry():
    if not session.get('logged_in'):
        abort(401)
    db = get_db()
    db.execute('INSERT INTO entries (title, text) VALUES (?, ?)',
               [request.form['title'], request.form['text']])
    db.commit()
    flash('New entry was successfully posted')
    return redirect(url_for('show_entries'))

if __name__ == '__main__':
    debug_mode = os.getenv('FLASK_DEBUG', 'False').lower() in ('true', '1')
    app.run(debug=debug_mode)

from flask import Flask, request, jsonify
import flask_tasks
from flask_caching import Cache
import time

# Application instance
application = Flask(__name__)

# Cache configuration
cache = Cache(application, config={
    'CACHE_TYPE': 'redis',
    'CACHE_REDIS_URL': 'redis://localhost:6379/0'
})

# Route: Time‑intensive computation
@application.route('/time-intensive')
@cache.memoize(timeout=50)
def heavy_operation():
    time.sleep(10)               # Simulate a heavy operation
    return 'Done!'

# Route: Clear cache for heavy_operation
@application.route('/clear_cache')
def reset_cache():
    cache.delete_memoized(heavy_operation)
    return 'Cache cleared!'

# Route: Fetch data with caching
@application.route('/data/<id>')
@cache.cached(timeout=50, make_cache_key=lambda: make_cache_key())
def get_data(id):
    time.sleep(5)                # Simulate expensive data retrieval
    return jsonify({'id': id, 'data': f'Data for {id}'})

# Custom cache key generator
def make_cache_key():
    path = request.path
    args_hash = str(hash(frozenset(request.args.items())))
    return f'{path}_{args_hash}'.encode('utf-8')

# Route: Home page
