from flask import Flask, request, abort
import flask_tasks
import json
import os
import serial

s = None
enum_values = ['0', '1']

def setup():
    global s
    s = serial.Serial("/dev/ttyS0", 57600)

f = os.popen('ifconfig apcli0 | grep "inet\\ addr" | cut -d: -f2 | cut -d" " -f1')
inet_addr = f.read()
application = Flask(__name__)

@application.route("/api/switchServo")
def control_servo():
    status = request.args.get("status")
    if not status:
        abort(404)
    status = status.encode("ascii")
    if status not in enum_values:
        abort(404)

    if status == '1':
        s.write("servo1")
    else:
        s.write("servo0")
    return json.dumps({"status": 200, "message": s.readline().strip()})

if __name__ == '__main__':
    setup()
    application.debug = True
    application.run(host=inet_addr, port=5000)

