        self._report_params = {
            'start_date': params.get('start_date'),
            'end_date': params.get('end_date')
        }


class RHApiEventHandler(RHApiBaseHandler):
    def _checkParams(self, params):
        super()._checkParams(params)
        self._report_params.update({
            'event_id': params['confId'],
            'contrib_id': params.get('contrib_id')
        })


class RHApiDownloadsHandler(RHApiEventHandler):
    def _checkParams(self, params):
        super()._checkParams(params)
