          <th onclick="sortTable('age')">Age</th>
        </tr>
      </thead>
      <tbody>
        {% for item in data %}
        <tr>
          <td>{{ loop.index }}</td>
          <td>{{ item.name }}</td>
          <td>{{ item.age }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>

    <script>
    let sort_direction = 'asc';
    function sortTable(sort_column) {
        $.ajax({
            type: "POST",
            url: "/sort",
            data: JSON.stringify({
                sort_column: sort_column,
                sort_direction: sort_direction
            }),
            contentType: "application/json",
            dataType: "json",
            success: function(response) {
                const tbody = $('#myTable tbody');
                tbody.empty();
                response.data.forEach((item, index) => {
                    const row = `<tr><td>${index + 1}</td><td>${item.name}</td><td>${item.age}</td></tr>`;
                    tbody.append(row);
                });
                sort_direction = sort_direction == 'asc' ? 'desc' : 'asc';
            }
        });
    }
    </script>
