        return config.is_activated()
    except Exception as exc:
        logger.error(f'unable to verify activation status, assume it is not activated, {exc}')
        return False


def no_cache(f):
    @wraps(f)
    def inner(*args, **kwargs):
        resp = make_response(f(*args, **kwargs))
        resp.headers['Cache-Control'] = (
            'no-store, no-cache, must-revalidate, post-check=0, pre-check=0, max-age=0'
        )
        return resp
    return inner


def fail_if_not_activated(f):
    @wraps(f)
    def inner(*args, **kwargs):
        if is_activated():
            return make_response(f(*args, **kwargs))
        return 'Device is not activated', 501
    return inner


def fail_if_activated(f):
    @wraps(f)
    def inner(*args, **kwargs):
        if is_activated():
            return 'Device is activated', 502
        return make_response(f(*args, **kwargs))
    return inner

