from flask import Flask, request, jsonify
import flask_tasks
from sqlalchemy import create_engine, text

def create_app():
    app = Flask(__name__)

    db_url = os.getenv('DATABASE_URL', 'postgresql://postgres:example@db:5432/postgres')
    engine = create_engine(db_url)

    services = {
        'user': 'http://user-service:5001',
        'order': 'http://order-service:5002',
        'inventory': 'http://inventory-service:5003',
        'payment': 'http://payment-service:5004',
        'shipping': 'http://shipping-service:5005',
    }

    @app.route('/status')
    def status():
        try:
            with engine.connect() as conn:
                conn.execute(text('SELECT 1'))
            return jsonify({'db': 'connected'}), 200
        except Exception as e:
            return jsonify({'db': 'error', 'detail': str(e)}), 500

    @app.route('/data')
    def data():
        try:
            with engine.connect() as conn:
                rows = conn.execute(text('SELECT * FROM sample_table LIMIT 5')).fetchall()
            return jsonify([dict(row) for row in rows]), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @app.route('/api/<name>', methods=['GET', 'POST', 'PUT', 'DELETE'])
    def gateway(name):
        if name not in services:
            return jsonify({'error': 'Unknown service'}), 404
        target = f"{services[name]}/{request.path.lstrip('/')}"
        try:
            r = requests.request(
                method=request.method,
                url=target,
                headers=request.headers,
                data=request.get_data(),
                params=request.args,
                timeout=5
            )
            return (r.content, r.status_code, r.headers.items())
        except requests.RequestException as e:
            return jsonify({'error': str(e)}), 502

    return app

app = create_app()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=True)

