    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

def classify_bmi(bmi):
    if bmi < 18.5:
        return 'Underweight'
    elif bmi < 24.9:
        return 'Normal weight'
    elif bmi < 29.9:
        return 'Overweight'
    else:
        return 'Obesity'

