# app instance
blog_app = Flask(__name__)
blog_app.config.from_object(__name__)

# database connection helper
def connect_db():
    return sqlite3.connect(blog_app.config['DATABASE'])

# login required decorator
def login_required(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if 'logged_in' in session:
            return func(*args, **kwargs)
        flash('You need to login first.')
        return redirect(url_for('perform_login'))
    return wrapper

# routes
@blog_app.route('/logout')
def perform_logout():
    session.pop('logged_in', None)
    flash('You were logged out')
    return redirect(url_for('perform_login'))

@blog_app.route('/main')
@login_required
def show_main():
    g.db = connect_db()
    cur = g.db.execute('SELECT * FROM posts')
    posts = [{'title': row[0], 'post': row[1]} for row in cur.fetchall()]
    g.db.close()
    return render_template('main.html', posts=posts)

@blog_app.route('/add', methods=['POST'])
@login_required
def add_post():
    title = request.form['title']
    post = request.form['post']
    if not title or not post:
        flash("All fields are required. Please try again.")
        return redirect(url_for('show_main'))
    g.db = connect_db()
    g.db.execute('INSERT INTO posts (title, post) VALUES (?,?)',
                 [title, post])
    g.db.commit()
    g.db.close()
    flash('New entry was successfully posted!')
    return redirect(url_for('show_main'))

@blog_app.route('/', methods=['GET', 'POST'])
def perform_login():
    error = None
    if request.method == 'POST':
        if (request.form['username'] != blog_app.config['USERNAME'] or
                request.form['password'] != blog_app.config['PASSWORD']):
            error = 'Invalid Credentials, Please try again.'
        else:
            session['logged_in'] = True
            return redirect(url_for('show_main'))
    return render_template('login.html', error=error)

if __name__ == '__main__':
    blog_app.run(debug=True)

