def plugin_infos(plugins):
    def plugin_info(plugin):
        return {
            'contexts': plugin.contexts,
            'groups': plugin.groups,
            'category': plugin.category,
        }

    return {p.name: plugin_info(p) for p in plugins}

# JSON API
