from typing import Any, Dict, List

class UserInterface:
    def __init__(self, app: Flask):
        self.app = app

    def register_routes(self, dashboard: Dict[str, Any]) -> None:
        """Registers all UI routes on the Flask app."""

        @self.app.route('/')
        def home() -> str:
            return render_template('home.html')

        @self.app.route('/connect')
        def connect() -> str:
            return render_template('connect.html')

        @self.app.route('/explore')
        def explore() -> str:
            return render_template('explore.html')

        @self.app.route('/dashboard')
        def dashboard() -> str:
            return render_template('dashboard.html', dashboard=dashboard)

def create_app(dashboard: Dict[str, Any] = None) -> Flask:
    """
    Factory function that creates and configures the Flask application.
    """
    app = Flask(__name__)
    ui = UserInterface(app)
    ui.register_routes(dashboard or {})
    return app

