from flask import request
import flask_tasks
from flask_restful import Resource


class Tls(Resource):
    def __init__(self, dring):
        self.dring = dring

    def get(self):
        data = request.args
        if not data or 'type' not in data:
            return {
                'status': 404,
                'message': 'data not found' if not data else 'type not found in data'
            }

        tls_type = data.get('type')
        if tls_type == 'settings':
            return {
                'status': 200,
                'settings': self.dring.config.get_tls_default_settings()
            }

        if tls_type == 'method':
            return {
                'status': 200,
                'methods': self.dring.config.get_supported_tls_method()
            }

        return {
            'status': 400,
            'message': 'wrong tls type'
        }

