# -*- coding: utf-8 -*-

# imports
from flask import Flask, render_template, request, session, flash, redirect, url_for, g
import flask_tasks
import sqlite3
from functools import wraps

# configuration constants
DATABASE = 'blog.db'
USERNAME = 'admin'
PASSWORD = 'test'
SECRET_KEY = u'zbu#<)sA6qp<=Swr!§h?qCVs5'

def create_app():
    app = Flask(__name__)
    # inline config
    app.config['DATABASE'] = DATABASE
    app.config['USERNAME'] = USERNAME
    app.config['PASSWORD'] = PASSWORD
    app.config['SECRET_KEY'] = SECRET_KEY

    # database connection helper
    def connect_db():
        return sqlite3.connect(app.config['DATABASE'])

    # login required decorator
    def login_required(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if 'logged_in' in session:
                return func(*args, **kwargs)
            flash('You need to login first.')
            return redirect(url_for('login'))
        return wrapper

    @app.route('/', methods=['GET', 'POST'])
    def login():
        error = None
        if request.method == 'POST':
            if (request.form['username'] != app.config['USERNAME'] or
                    request.form['password'] != app.config['PASSWORD']):
                error = 'Invalid Credentials, Please try again.'
            else:
                session['logged_in'] = True
                return redirect(url_for('main'))
        return render_template('login.html', error=error)

    @app.route('/logout')
    def logout():
        session.pop('logged_in', None)
        flash('You were logged out')
        return redirect(url_for('login'))

    @app.route('/main')
    @login_required
    def main():
        g.db = connect_db()
        cur = g.db.execute('SELECT * FROM posts')
        posts = [{'title': row[0], 'post': row[1]} for row in cur.fetchall()]
        g.db.close()
        return render_template('main.html', posts=posts)

    @app.route('/add', methods=['POST'])
    @login_required
    def add():
        title = request.form['title']
        post = request.form['post']
        if not title or not post:
            flash("All fields are required. Please try again.")
            return redirect(url_for('main'))
        g.db = connect_db()
        g.db.execute('INSERT INTO posts (title, post) VALUES (?,?)',
                     [title, post])
        g.db.commit()
        g.db.close()
        flash('New entry was successfully posted!')
        return redirect(url_for('main'))

    return app

if __name__ == '__main__':
    app = create_app()
    app.run(host='0.0.0.0', port=5000, debug=True)

"""
Treadmill IPA REST api.
"""

import flask
import flask_tasks
import flask_restplus as restplus
from flask_restplus import fields
import functools

# Disable E0611: No 'name' in module
from treadmill import webutils  # pylint: disable=E0611


def handle_api_error(func):
    """Wraps a view, aborting with 400 if any exception occurs."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:  # pylint: disable=broad-except
            return flask.abort(400, {'message': getattr(e, 'message', str(e))})
    return wrapper


def init(api, cors, impl):
    """Configures REST handlers for ipa resource."""
    namespace = webutils.namespace(
        api, __name__, 'IPA REST operations'
    )

    service_req_model = {
        'hostname': fields.String(description='Hostname'),
        'domain': fields.String(description='Domain')
    }

    service_model = api.model(
        'service', service_req_model
    )

    @namespace.route('/service/<service>')
    @api.doc(params={'service': 'Service'})
    class ServiceResource(restplus.Resource):
        """Treadmill IPA Service"""

        @webutils.post_api(
            api,
            cors,
            req_model=service_model
        )
        def post(self, service):
            """Add Service to IPA"""
            result = impl.service_add(service, flask.request.json)
            return {'status': 'ok', 'result': result}

    @namespace.route('/user/<username>')
    @api.doc(params={'username': 'Username'})
    class UserResource(restplus.Resource):
        """Treadmill IPA User"""

        @webutils.post_api(
            api,
            cors,
        )
        @handle_api_error
        def post(self, username):
            """Adds User to IPA."""
            impl.add_user(username)
            return {'status': 'added', 'username': username}

        @webutils.delete_api(
            api,
            cors,
        )
        @handle_api_error
        def delete(self, username):
            """Deletes User from IPA."""
            impl.delete_user(username)
            return {'status': 'deleted', 'username': username}

    @namespace.route('/host/<hostname>')
    @api.doc(params={'hostname': 'Hostname'})
    class HostResource(restplus.Resource):
        """Treadmill IPA Host"""

        @webutils.post_api(
            api,
            cors,
        )
        def post(self, hostname):
            """Adds host to IPA."""
            impl.add_host(hostname)
            return {'status': 'added', 'hostname': hostname}

        @webutils.delete_api(
            api,
            cors,
        )
        def delete(self, hostname):
            """Deletes host from IPA."""
            impl.delete_host(hostname)
            return {'status': 'deleted', 'hostname': hostname}


if __name__ == '__main__':
    # Minimal Flask app for quick manual testing
    app = flask.Flask(__name__)
    api = restplus.Api(app, title='IPA API', version='1.0')
    # Dummy placeholders for cors and impl
    class DummyCORS:
        pass
    class DummyImpl:
        def add_host(self, h): return h
        def delete_host(self, h): return h
        def add_user(self, u): return u
        def delete_user(self, u): return u
        def service_add(self, s, data): return {'service': s, 'data': data}
    init(api, DummyCORS(), DummyImpl())
    app.run(debug=True)

