import ssl
import sys
import logging
import os.path

import flask
import flask_tasks

import webserver_sub

app = flask.Flask(__name__)

# Route defined before logging hooks for readability
@app.route('/')
def hello_world():
    return "Hello World via SSL!"

@app.after_request
def log_request(response):
    return webserver_sub.log_request(response)

@app.before_first_request
def turn_off_logging():
    logging.getLogger('werkzeug').setLevel(logging.ERROR)

def _create_ssl_context():
    """Return an SSLContext configured for TLSv1.2."""
    ssl_dir = os.path.join(
        os.path.abspath(os.path.dirname(__file__)), 'data', 'ssl')
    # pylint: disable=no-member, useless-suppression
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLSv1_2)
    ctx.load_cert_chain(
        os.path.join(ssl_dir, 'cert.pem'),
        os.path.join(ssl_dir, 'key.pem')
    )
    return ctx

def main():
    app.run(
        port=int(sys.argv[1]),
        ssl_context=_create_ssl_context(),
        debug=False
    )

if __name__ == '__main__':
    main()

