from flask import Blueprint, request, jsonify
import flask_tasks
from flask.ext.login import current_user
from flask.ext.babel import gettext as _

from .services import add_user_interest, remove_user_interest


def create_interested_blueprint():
    interested = Blueprint('interested', __name__, url_prefix='/interested')

    @interested.route('/<type>/<id>', methods=['POST'])
    def toggle(type, id):
        if current_user.is_anonymous():
            return jsonify({'anon': True})
        """ Toggles current user's interest in a proposal """
        from app.mod_proposal import Proposal
        from app.mod_event import Event

        user = current_user._get_current_object()
        remove = request.form.get('action', 'add') == 'remove'
        attribute = request.form.get('attribute') or None
        cls = Event if type == 'event' else Proposal

        obj = cls.objects.get_or_404(id=id)

        if remove:
            remove_user_interest(user, obj, cls, only=attribute)
        else:
            add_user_interest(user, obj, cls, extra=attribute)

        interested_users = [u.display_name for u in obj.interested_users]

        return jsonify({
            'num_interested': obj.num_interested,
            'next': 'remove' if obj.user_is_interested(user) else 'add',
            'interested_users': interested_users
        })

    return interested

"""
HTTP Basic Auth decorator returning dicts and using helper functions.
"""

from functools import wraps

from flask import request, current_app
import flask_tasks


def _make_error(message, status):
    """Return a dict representing an error response."""
    return {'message': message, 'statusCode': status}, status


def _verify_credentials():
    """Return tuple of required credentials or raise KeyError."""
    cfg = current_app.config['basic_auth_credentials']
    return cfg['username'], cfg['password']


def basic_auth(func):
    """
    Decorator that validates HTTP Basic Auth credentials.
    Responds with JSON dicts on failure.
    """

    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            required = _verify_credentials()
        except (KeyError, TypeError):
            return _make_error('Server credential store setup incomplete.', 500)

        auth = request.authorization
        if not auth:
            return _make_error('HTTP Basic Auth required for this URL.', 401)

        provided = auth.username, auth.password
        if provided != required:
            return _make_error(
                'Could not verify your access level for that URL. You have to login with proper credentials',
                401)

        return func(*args, **kwargs)

    return wrapper

