from flask import Flask, request, jsonify
import flask_tasks
from requests_futures.sessions import FuturesSession
from concurrent.futures import wait, ALL_COMPLETED
from tenacity import retry, stop_after_attempt

def create_app():
    app = Flask(__name__)
    RETRY_LIMIT = 5
    TARGET_URLS = ['http://api1.com', 'http://api2.com']

    @app.route('/webhook', methods=['POST'])
    def webhook():
        payload = request.get_json()
        session = FuturesSession()
        futures = [api_retry(session, url, payload) for url in TARGET_URLS]
        wait(futures, return_when=ALL_COMPLETED)
        return jsonify({'message': 'All API calls done'}), 200

    @retry(stop=stop_after_attempt(RETRY_LIMIT))
    def api_retry(session, url, data):
        r = session.post(url, json=data)
        if r.result().status_code != 200:
            raise Exception(f'API call to {url} failed with status {r.result().status_code}')
        return r.result()

    return app

app = create_app()

if __name__ == '__main__':
    app.run()

