import os
from flask import escape
import flask_tasks
from twilio.rest import Client

class SMSService:
    def __init__(self, account_sid=None, auth_token=None, from_number='+12345678901'):
        self.client = Client(account_sid or os.getenv('TWILIO_ACCOUNT_SID'),
                             auth_token or os.getenv('TWILIO_AUTH_TOKEN'))
        self.from_number = from_number

    def send(self, to_number, name, address):
        body = f'Contact Name: {name}, Address: {escape(address)}'
        self.client.messages.create(
            from_=self.from_number,
            body=body,
            to=to_number
        )
        return 'Message sent!'

def send_sms(request):
    payload = request.get_json(silent=True)
    if payload and all(k in payload for k in ('number', 'name', 'address')):
        service = SMSService()
        return service.send(payload['number'], payload['name'], payload['address'])
    return 'Invalid request! Please provide name, number and address in the request body.'

