from MyConfig import MyConfig
from Utilities import debug_msg


class AppSingleton:
    class _AppSingleton:
        flask_app = None
        db = None
        config = MyConfig()

        def global_create_app(self, name, db_path):
            basedir = os.path.abspath(os.path.dirname(__file__))
            if name is None:
                debug_msg("Warning: no app name!")
                name = '__main__'

            self.flask_app = Flask(name)

            if db_path is None:
                database_path = (
                    f"sqlite:///{os.path.join(basedir, self.config.getConfig('database_path'))}"
                )
            else:
                database_path = (
                    f"sqlite:///{os.path.join(basedir, db_path)}"
                )
            debug_msg(f"----database_path---: {database_path}")
            self.flask_app.config['SQLALCHEMY_DATABASE_URI'] = database_path
            debug_msg(self.flask_app.config['SQLALCHEMY_DATABASE_URI'])
            self.flask_app.config['SQLALCHEMY_COMMIT_ON_TEARDOWN'] = True
            return self.flask_app

        def global_create_db(self, app):
            self.db = SQLAlchemy(app)
            return self.db

        def get_global_db(self):
            return self.db

        def get_global_app(self):
            return self.flask_app

        def __init__(self):
            pass

    _instance = None

    def __init__(self):
        if not AppSingleton._instance:
            AppSingleton._instance = AppSingleton._AppSingleton()

    def __getattr__(self, name):
        return getattr(self._instance, name)

