def create_app():
    # Create the Flask application
    app = Flask(__name__)

    # Inline cache configuration
    cache_config = {'CACHE_TYPE': 'SimpleCache'}
    cache = Cache(app, config=cache_config)

    # Cached index route
    @app.route('/')
    @cache.cached(timeout=50)
    def index():
        return 'Welcome to the cached index page!'

    # Memoized expensive function
    @cache.memoize(50)
    def get_expensive_data():
        # Simulated expensive operation
        return {'data': 'expensive result'}

    # Route that invokes the memoized function
    @app.route('/expensive')
    def expensive():
        return jsonify(get_expensive_data())

    # Cache clear endpoint
    @app.route('/clear')
    def clear_cache():
        cache.clear()
        return 'Cache cleared'

    return app

