import sys
# Disable creating .pyc files
sys.dont_write_bytecode = True

import os
import flask
import flask_tasks
import jinja_patch
from jutsu.lib.plugins import get_plugins
from jutsu.lib.db import db_session

class JutsuApplication(flask.Flask):
    def send_static_file(self, filename):
        """Patch for static folder search path across blueprints."""
        for bp in self.blueprints.values():
            path = os.path.join(bp.static_folder, filename)
            if os.path.exists(path):
                return flask.send_from_directory(bp.static_folder, filename)
        return super().send_static_file(filename)

    def __init__(self, name):
        super().__init__(name)
        jinja_patch.apply_patch(self)

        @self.teardown_appcontext
        def remove_session(exception=None):
            db_session.remove()

    def run(self, **kwargs):
        plugins = get_plugins()
        for plugin in plugins:
            ui = plugin.get_ui()
            if ui is not None:
                ui_mod = sys.modules[ui.__module__]
                ui_mod.app = self
                prefix = '/' if plugin.get_name() == "core" else f'/{plugin.get_name()}'
                self.register_blueprint(ui.page, url_prefix=prefix)
        super().run(**kwargs)

if __name__ == '__main__':
    application = JutsuApplication(__name__)
    application.run(debug=True, use_reloader=False)

