class OAuthUser(BaseUser):
    type = 'oauth'
    provider = None

    def __init__(self, provider, user_id, username=None, token=None, email=None):
        self.provider = provider
        self.username = username
        self.email = email
        self.id = user_id
        self.token = token
        self.auth_id = "{0}-{1}".format(provider, username)

    @property
    def auth_token_id(self):
        return self.token

    @staticmethod
    def load_user(*args, **kwargs):
        return OAuthUser.fetch_by_id(args[0])

    @staticmethod
    def fetch_by_id(user_id):
        return user_registry.get(user_id)

    @staticmethod
    def authenticate(provider, data, oauth_token):
        field_map = providers.get(provider).get('field_map')
        if not field_map:
            raise NotImplementedError

        def get_value(d, key):
            if isinstance(key, basestring):
                return d.get(key)
            elif callable(key):
                return key(d)
            val = d.get(key.pop(0))
            if len(key) == 0:
                return val
            return get_value(val, key)

        fields = {}
        for k, v in field_map.items():
            fields[k] = get_value(data, v)

        user = OAuthUser(provider, fields['id'], username=fields.get('username'), email=fields.get('email'),
                         token=OAuthUser.hash_password(oauth_token))
        user_registry[user.auth_id] = user

        if user:
            login_user(user, remember=True)
            return True
        else:
            return False

    @classmethod
    def get_oauth_app(cls, provider):
        if oauth_client.remote_apps.get(provider):
            return oauth_client.remote_apps.get(provider)
        app = oauth_client.remote_app(
            provider,
            consumer_key=config.OAUTH.get(provider, {}).get('key'),
            consumer_secret=config.OAUTH.get(provider, {}).get('secret'),
            **providers[provider]['oauth'])
        app.tokengetter(lambda: session.get(provider + "_token"))
        return app

    @classmethod
    def get_provider_setting(cls, provider, key):
        return providers.get(provider, {}).get(key)

    @classmethod
    def retrieve_token(cls, provider, resp):
        return resp.get(cls.get_provider_setting(provider, 'token_name'))

    def get_user_id(self):
        return unicode("{0}/{1}".format(self.type, self.auth_id))

    @staticmethod
    def render_login_form():
        buttons = []
        for name, val in providers.items():
            if not config.OAUTH.get(name, {}).get('key') or not config.OAUTH.get(name, {}).get('secret'):
                continue
            buttons.append(val.get('button'))

        return "<h3>Social Login</h3>" + " ".join(buttons)

