import configparser
import importlib

config = configparser.ConfigParser()
config.read("config.ini")

bots = {}
for bot in config.sections():
    if "disabled" in config[bot] and config[bot]["webhook"] == "1":
        print(f"Bot {bot} disabled")
        continue
    if "webhook" not in config[bot] or config[bot]["webhook"] != "1":
        print(f"Bot {bot} not using webhook")
        continue
    if "repo_name" not in config[bot]:
        raise RuntimeError(f"Cannot find repo for bot {bot}")
    bot_path = os.path.join(os.getcwd(), config[bot]["repo_name"])
    if not os.path.isdir(bot_path):
        raise RuntimeError(f"Cannot find path {bot_path} for bot {bot}")
    sys.path.append(bot_path)
    if "module_name" not in config[bot]:
        raise RuntimeError(f"Cannot find module for bot {bot}")
    module_name = config[bot]["module_name"]
    importlib.import_module(module_name)
    bots[config[bot]["token"]] = getattr(sys.modules[module_name], "create_webhook_bot")(config[bot])

if len(bots) == 0:
    raise RuntimeError("Not running any bots!")

