from twilio.rest import Client

def _build_twilio_client():
    return Client(os.getenv('TWILIO_ACCOUNT_SID'), os.getenv('TWILIO_AUTH_TOKEN'))

def _compose_message(name, address):
    return f'Contact Name: {name}, Address: {address}'

def send_sms(request):
    data = request.get_json(silent=True)

    if data and {'number', 'name', 'address'} <= data.keys():
        body = _compose_message(data['name'], escape(data['address']))
        client = _build_twilio_client()
        client.messages.create(
            from_='+12345678901',
            body=body,
            to=data['number']
        )
        return 'Message sent!'
    return 'Invalid request! Please provide name, number and address in the request body.'

