class _MailgunClient:
    """Internal client that encapsulates Mailgun communication."""
    def __init__(self, conf):
        self.conf = conf

    def _send(self, to, subject, body, v=None):
        conf = self.conf
        if env.get('BRV_SANDBOX') == 'True':
            test_db = current_app.db_client['test']
            cred = test_db.credentials.find_one()['mailgun']
            conf = cred
            log.debug('sandbox mode. using domain="%s"', conf['domain'])
            to = conf['sandbox_to']

        data = {
            'from': conf['from'],
            'to': to,
            'subject': subject,
            'html': body,
        }

        if v:
            for k in v:
                data['v:' + k] = v[k]

        try:
            response = requests.post(
                f"https://api.mailgun.net/v3/{conf['domain']}/messages",
                auth=('api', conf['api_key']),
                data=data,
            )
        except requests.RequestException:
            g.group = g.db['groups'].find_one({'mailgun.from': conf['from']})
            log.exception('Mailgun error')
            raise

        if response.status_code == requests.codes.ok:
            return json.loads(response.text)['id']
        else:
            raise Exception(f'Error sending email to "{to}"')

    def dump(self, form_values):
        form_values['message-headers'] = json.loads(form_values['message-headers'])
        log.debug(json.dumps(form_values, sort_keys=True, indent=4))

#-------------------------------------------------------------------------------
def send(to, subject, body, conf, v=None):
    """Public send helper that creates a transient client."""
    client = _MailgunClient(conf)
    return client._send(to, subject, body, v)

def dump(form_values):
    """Public dump helper that creates a transient client."""
    client = _MailgunClient(None)
    client.dump(form_values)

