class Subscriber(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), index=True, unique=True)
    datesubbed = db.Column(db.String(12), index=True, unique=False)

    def __str__(self) -> str:
        return f"{self.email} subscribed on {self.datesubbed}"

    @staticmethod
    def _format_subscriber(sub: 'Subscriber') -> str:
        return f"{sub}<br/>"

    @staticmethod
    def add(address: str) -> None:
        date = str(datetime.date.today())
        new_sub = Subscriber(email=address, datesubbed=date)
        db.session.add(new_sub)
        db.session.commit()

    @staticmethod
    def remove(address: str) -> None:
        sub = Subscriber.query.filter_by(email=address).first()
        if sub:
            db.session.delete(sub)
            db.session.commit()

    @staticmethod
    def list() -> str:
        subs = Subscriber.query.all()
        return ''.join(Subscriber._format_subscriber(s) for s in subs)

