from flask_restful import Api, Resource
from flask import jsonify, request
import flask_tasks


class Tls(Resource):
    def __init__(self, dring):
        self.dring = dring

    def get(self):
        args = request.args
        if not args:
            return jsonify({
                'status': 404,
                'message': 'data not found'
            })

        if 'type' not in args:
            return jsonify({
                'status': 404,
                'message': 'type not found in data'
            })

        tls_type = args.get('type')
        if tls_type == 'settings':
            return jsonify({
                'status': 200,
                'settings': self.dring.config.get_tls_default_settings()
            })

        if tls_type == 'method':
            return jsonify({
                'status': 200,
                'methods': self.dring.config.get_supported_tls_method()
            })

        return jsonify({
            'status': 400,
            'message': 'wrong tls type'
        })


def create_app(dring):
    app = Flask(__name__)
    api = Api(app)

    # Create a subclass that captures the dring instance
    class TlsWithDring(Tls):
        def __init__(self):
            super().__init__(dring)

    api.add_resource(TlsWithDring, '/tls')
    return app


