from flask import Flask, request, jsonify
import flask_tasks
from flask_caching import Cache

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'simple'})

OMDB_API_KEY = 'your_api_key_here'


@app.route('/search', methods=['GET'])
def search_movie():
    movie_title = request.args.get('title')
    release_year = request.args.get('year')

    if not movie_title or not release_year:
        return jsonify({'error': 'Both title and year parameters are required'}), 400

    cached_movie = cache.get(f'{movie_title}_{release_year}')
    if cached_movie:
        return jsonify(cached_movie)

    response = requests.get(
        f'http://www.omdbapi.com/?t={movie_title}&y={release_year}&apikey={OMDB_API_KEY}')
    movie = response.json()

    if movie['Response'] == 'False':
        return jsonify({'error': 'Movie not found'}), 404

    if movie['Rated'] == 'Adult':
        return jsonify({'error': 'Adult rated movies are not allowed'}), 403

    cache.set(f'{movie_title}_{release_year}', movie, timeout=5 * 60)

    return jsonify(movie)


