    data = json.loads(request.data.decode())
    mandatory_items = ['baby_gender', 'mother_age',
                       'plurality', 'gestation_weeks']
    for item in mandatory_items:
        if item not in data.keys():
            return {'result': 'Set all items.'}

    features = {
        'key': 'nokey',
        'is_male': _gender_str(data['baby_gender']),
        'mother_age': float(data['mother_age']),
        'plurality': _plurality_str(data['plurality'],
                                    _gender_str(data['baby_gender'])),
        'gestation_weeks': float(data['gestation_weeks']),
    }

    prediction = get_prediction(features)
    return {'result': '{:.2f} lbs.'.format(prediction)}


