from flask import Flask, request, jsonify
import flask_tasks
from flask_caching import Cache

flask_app = Flask(__name__)
cache = Cache(flask_app, config={'CACHE_TYPE': 'simple'})

OMDB_API_KEY = 'your_api_key_here'


@flask_app.route('/find', methods=['GET'])
def retrieve_movie():
    title = request.args.get('title')
    year = request.args.get('year')

    if not title or not year:
        return jsonify({'error': 'Both title and year parameters are required'}), 400

    key = f'{title}_{year}'
    cached = cache.get(key)
    if cached:
        return jsonify(cached)

    resp = requests.get(f'http://www.omdbapi.com/?t={title}&y={year}&apikey={OMDB_API_KEY}')
    data = resp.json()

    if data.get('Response') == 'False':
        return jsonify({'error': 'Movie not found'}), 404

    if data.get('Rated') == 'Adult':
        return jsonify({'error': 'Adult rated movies are not allowed'}), 403

    cache.set(key, data, timeout=5 * 60)

    return jsonify(data)


