class MusicBrainzOAuth:
    def __init__(self, client_id, client_secret, session_key='musicbrainz'):
        self._service = OAuth2Service(
            name='musicbrainz',
            base_url="https://musicbrainz.org/",
            authorize_url="https://musicbrainz.org/oauth2/authorize",
            access_token_url="https://musicbrainz.org/oauth2/token",
            client_id=client_id,
            client_secret=client_secret,
        )
        self._sess_key = session_key

    def _persist_data(self, **kwargs):
        if self._sess_key not in session:
            session[self._sess_key] = dict()
        session[self._sess_key].update(**kwargs)
        session.modified = True

    def _fetch_data(self, key, default=None):
        if self._sess_key not in session:
            return None
        return session[self._sess_key].get(key, default)

    def get_user(self):
        s = self._service.get_auth_session(
            data={
                'code': self._fetch_data('code'),
                'grant_type': 'authorization_code',
                'redirect_uri': url_for('login.musicbrainz_post', _external=True)
            },
            decoder=lambda b: ujson.loads(b.decode("utf-8"))
        )
        data = s.get('oauth2/userinfo').json()
        musicbrainz_id = data.get('sub')
        musicbrainz_row_id = data.get('metabrainz_user_id')

        user = db_user.get_by_mb_row_id(musicbrainz_row_id, musicbrainz_id)
        user_email = None
        if mb_engine:
            user_email = mb_editor.get_editor_by_id(musicbrainz_row_id)['email']

        if user is None:
            if current_app.config["REJECT_NEW_USERS_WITHOUT_EMAIL"] and user_email is None:
                return None
            db_user.create(musicbrainz_row_id, musicbrainz_id, email=user_email)
            user = db_user.get_by_mb_id(musicbrainz_id, fetch_email=True)
            ts.set_empty_cache_values_for_user(musicbrainz_id)
        else:
            user = dict(user)
            user["email"] = user_email
            db_user.update_user_email(musicbrainz_id, user_email)

        return user

    def get_authentication_uri(self):
        csrf = generate_string(20)
        self._persist_data(csrf=csrf)
        params = {
            'response_type': 'code',
            'redirect_uri': url_for('login.musicbrainz_post', _external=True),
            'scope': 'profile',
            'state': csrf,
        }
        return self._service.get_authorize_url(**params)

    def validate_post_login(self):
        if request.args.get('error'):
            return False
        if self._fetch_data('csrf') != request.args.get('state'):
            return False
        code = request.args.get('code')
        if not code:
            return False
        self._persist_data(code=code)
        return True


