from wordcloud import WordCloud
from matplotlib import pyplot as plt
from sklearn.datasets import fetch_20newsgroups
from flask import Flask, request, jsonify
import flask_tasks

def create_app():
    app = Flask(__name__)
    app.config['DEBUG'] = True

    newsgroups_data = fetch_20newsgroups(remove=('headers', 'footers', 'quotes'))
    topics = newsgroups_data.target_names

    def word_cloud(topic, num_words):
        idx = [i for i, t in enumerate(newsgroups_data.target) if t == topics.index(topic)]
        texts = [newsgroups_data.data[i] for i in idx]
        text = ' '.join(texts)

        wc = WordCloud(max_words=num_words).generate(text)

        plt.imshow(wc, interpolation='bilinear')
        plt.axis('off')
        plt.show()

    @app.route('/wordcloud', methods=['GET'])
    def get_wordcloud():
        topic = request.args.get('topic')
        num_words = request.args.get('num_words')

        if not topic or not num_words:
            return jsonify({'error': 'Missing required parameter.'})

        if topic not in topics:
            return jsonify({'error': 'Invalid topic.'})

        try:
            num_words = int(num_words)
        except ValueError:
            return jsonify({'error': 'Number of words must be an integer.'})

        if num_words <= 0:
            return jsonify({'error': 'Number of words must be a positive integer.'})

        return word_cloud(topic, num_words)

    return app

if __name__ == '__main__':
    application = create_app()
    application.run(host='0.0.0.0', port=5000)

