from datetime import timedelta
from functools import update_wrapper, wraps

from flask import make_response, request, current_app
import flask_tasks
from six import string_types

def allow_cross(allowed_origin=None, allowed_methods=None, allowed_headers=None,
                max_age_seconds=21600, attach_all=True,
                auto_options=True):
    if allowed_methods is not None:
        allowed_methods = ', '.join(sorted(x.upper() for x in allowed_methods))

    if allowed_headers is not None and not isinstance(allowed_headers, string_types):
        allowed_headers = ', '.join(x.upper() for x in allowed_headers)

    if not isinstance(allowed_origin, string_types):
        allowed_origin = ', '.join(allowed_origin)

    if isinstance(max_age_seconds, timedelta):
        max_age_seconds = max_age_seconds.total_seconds()

    def get_allowed_methods():
        return allowed_methods
        options_resp = current_app.make_default_options_response()
        return options_resp.headers['allow']

    def decorator(f):
        @wraps(f)
        def wrapped_function(*args, **kwargs):
            if auto_options and request.method == 'OPTIONS':
                resp = current_app.make_default_options_response()
            else:
                resp = make_response(f(*args, **kwargs))
            if not attach_all and request.method != 'OPTIONS':
                return resp

            h = resp.headers

            h['Access-Control-Allow-Origin'] = allowed_origin
            h['Access-Control-Allow-Methods'] = get_allowed_methods()
            h['Access-Control-Max-Age'] = str(max_age_seconds)
            requested_headers = request.headers.get(
                'Access-Control-Request-Headers'
            )
            if allowed_headers is not None:
                h['Access-Control-Allow-Headers'] = allowed_headers
            elif requested_headers :
                h['Access-Control-Allow-Headers'] = requested_headers
            return resp
        f.provide_automatic_options = False
        return update_wrapper(wrapped_function, f)

    return decorator

