from __future__ import absolute_import

from datetime import timedelta
from functools import update_wrapper

from flask import make_response, request, current_app
import flask_tasks
from six import string_types

class CrossDomain:
    def __init__(self, origin=None, methods=None, headers=None,
                 max_age=21600, attach_to_all=True,
                 automatic_options=True):
        if methods is not None:
            self.methods = ', '.join(sorted(x.upper() for x in methods))
        else:
            self.methods = None

        if headers is not None and not isinstance(headers, string_types):
            self.headers = ', '.join(x.upper() for x in headers)
        else:
            self.headers = headers

        if not isinstance(origin, string_types):
            self.origin = ', '.join(origin)
        else:
            self.origin = origin

        if isinstance(max_age, timedelta):
            self.max_age = max_age.total_seconds()
        else:
            self.max_age = max_age

        self.attach_to_all = attach_to_all
        self.automatic_options = automatic_options

    def __call__(self, f):
        def get_methods():
            return self.methods
            options_resp = current_app.make_default_options_response()
            return options_resp.headers['allow']

        @update_wrapper(f, f)
        def wrapped_function(*args, **kwargs):
            if self.automatic_options and request.method == 'OPTIONS':
                resp = current_app.make_default_options_response()
            else:
                resp = make_response(f(*args, **kwargs))
            if not self.attach_to_all and request.method != 'OPTIONS':
                return resp

            h = resp.headers
            h['Access-Control-Allow-Origin'] = self.origin
            h['Access-Control-Allow-Methods'] = get_methods()
            h['Access-Control-Max-Age'] = str(self.max_age)
            requested_headers = request.headers.get(
                'Access-Control-Request-Headers'
            )
            if self.headers is not None:
                h['Access-Control-Allow-Headers'] = self.headers
            elif requested_headers:
                h['Access-Control-Allow-Headers'] = requested_headers
            return resp
        f.provide_automatic_options = False
        return wrapped_function

def crossdomain(origin=None, methods=None, headers=None,
                max_age=21600, attach_to_all=True,
                automatic_options=True):
    return CrossDomain(origin, methods, headers, max_age,
                       attach_to_all, automatic_options)

