"""
Flask API Blueprint for camera v1

A "camera controller" is any object that has one or more "cameras",
where a camera has the following properties -
- on : <bool>
- recording : <bool>
- alerts : <bool>

Allows for POST command to create new camera controller objects,
as well as PUT to modify and GET to view

Camera v1 implements a driver architecture,
importing pluggable drivers from the Hub/v1/Camera directory
All drivers should super the CameraDriver class and implement its methods
"""
from flask import Blueprint, request, make_response
import flask_tasks
import json

from Hub.v1.Common.auth import requires_auth
from Hub.v1.Common.helpers import int_or_string, bool_or_string, parse_request_value

from Hub.v1.Camera.Camera import CameraController, CAMERA_DRIVERS


def create_blueprint():
    bp = Blueprint('V1CAMERA', __name__)

    @bp.route('/v1/cameracontroller', methods=['POST'])
    @requires_auth
    def new_camera_controller():
        camera_controller_info = request.get_json(silent=True, cache=True)
        camera_controller = CameraController(**camera_controller_info)
        camera_controller.refresh()
        return _camera_controllers_internal(camera_controller_id=camera_controller.id)

    @bp.route('/v1/cameradrivers', methods=['GET'])
    @requires_auth
    def get_camera_drivers():
        return json.dumps(CAMERA_DRIVERS)

    @bp.route('/v1/cameracontroller', methods=['GET'])
    @requires_auth
    def get_camera_controllers():
        return _camera_controllers_internal(**request.args.to_dict(flat=True))

    @bp.route('/v1/cameracontroller/<path:path>', methods=['GET', 'PUT'])
    @requires_auth
    def get_camera_controller_path(path):
        parsed_path = path.split("/")
        path = map(int_or_string, parsed_path)
        value = parse_request_value(request)

        if len(path) > 1:
            return _camera_controllers_internal(camera_controller_id=path[0],
                                                path=path[1:],
                                                value=value)
        elif len(path) == 1:
            return _camera_controllers_internal(camera_controller_id=path[0],
                                                value=value)
        else:
            return _camera_controllers_internal()

    @bp.route('/v1/cameracontroller/<path:path>', methods=['DELETE'])
    @requires_auth
    def delete_camera_controller(path):
        parsed_path = path.split("/")
        parsed_path = map(int_or_string, parsed_path)
        camera_controller_id = parsed_path[0]
        if len(parsed_path) == 1:
            camera_controller = CameraController.get_id(camera_controller_id)
            if camera_controller:
                camera_controller.delete()
                return ""
        return make_response(json.dumps({"reason": "InvalidPath"}), 404)

    @bp.route('/v1/camera', methods=['GET'])
    @requires_auth
    def get_cameras():
        return _cameras_internal(**request.args.to_dict(flat=True))

    @bp.route('/v1/camera/<path:path>', methods=['GET', 'PUT'])
    @requires_auth
    def get_camera_path(path):
        parsed_path = path.split("/")
        path = map(int_or_string, parsed_path)
        value = parse_request_value(request)

        if len(path) > 1:
            return _cameras_internal(camera_id=path[0], path=path[1:], value=value)
        elif len(path) == 1:
            return _cameras_internal(camera_id=path[0], value=value)
        else:
            return _cameras_internal()

    def _camera_controllers_internal(camera_controller_id=None, path=None, value=None, **kwargs):
        if camera_controller_id is None:
            if value is not None:
                return make_response(json.dumps({"reason": "NotImplemented"}), 501)
            camera_controller_list = CameraController.list(dict_format=True, **kwargs)
            return json.dumps(camera_controller_list)

        camera_controller = CameraController.get_id(camera_controller_id)
        if not camera_controller:
            return make_response(json.dumps({"reason": "InvalidControllerID"}), 404)

        camera_controller_dict = camera_controller.dict()
        return_value = camera_controller_dict

        if path is None:
            path = []
        path_len = len(path)

        if value is None:
            for level in path:
                try:
                    return_value = return_value[level]
                except (KeyError, IndexError):
                    return make_response(json.dumps(
                        {"reason": f"BadGetPath-{level}"}), 404)
            return json.dumps(return_value)
        else:
            value = bool_or_string(value)
            if path_len == 3:
                if (path[0] == "cameras" and
                    path[1] in list(camera_controller.cameras)):
                    if path[2] in ["name", "allocated"]:
                        camera_controller.cameras[path[1]][path[2]] = value
                        camera_controller.save()
                        return json.dumps(camera_controller.cameras[path[1]][path[2]])
                    elif camera_controller.driver_class.set_camera(
                            camera_controller,
                            camera_controller.cameras[path[1]]['name'],
                            path[2],
                            value):
                        camera_controller.refresh()
                        return json.dumps(camera_controller.dict())
                    else:
                        return make_response(json.dumps(
                            {"reason": "NotImplementedPut3"}), 501)
                else:
                    return make_response(json.dumps(
                        {"reason": "InvalidInputPut3"}), 404)
            elif path_len == 2:
                if path[0] == "driver_info":
                    camera_controller.driver_info[path[1]] = value
                else:
                    return make_response(json.dumps(
                        {"reason": "NotImplementedPut2"}), 501)
                camera_controller.save()
                camera_controller_dict = camera_controller.dict()
                return json.dumps(camera_controller_dict[path[0]][path[1]])
            elif path_len == 1:
                if path[0] in ["name", "driver"]:
                    setattr(camera_controller, path[0], value)
                else:
                    return make_response(json.dumps(
                        {"reason": "NotImplementedPut1"}), 501)
                camera_controller.save()
                camera_controller_dict = camera_controller.dict()
                return json.dumps(camera_controller_dict[path[0]])
            else:
                return make_response(json.dumps(
                    {"reason": "NotImplementedPut0"}), 501)

        return make_response(json.dumps({"reason": "InvalidInputBottom"}), 404)

    def _cameras_internal(camera_id=None, path=None, value=None, **kwargs):
        if camera_id is None:
            if value is not None:
                return make_response(json.dumps({"reason": "InvalidInput"}), 501)
            camera_list = CameraController.list_available_cameras(**kwargs)
            return json.dumps(camera_list)
        else:
            if path is None:
                path = []
            camera_controller = CameraController.get_for_camera_id(camera_id)
            return _camera_controllers_internal(
                camera_controller_id=camera_controller.id,
                path=["cameras", camera_id] + path,
                value=value)

        return make_response(json.dumps({"reason": "PinNotFound"}), 404)

    return bp

